/**
 * Authentication policy for the FinGuard API.
 *
 * Token parsing and claim failures are authentication failures.  They must
 * never be downgraded into monitor-only events because downstream handlers
 * may otherwise serve data without an authenticated request context.
 */
'use strict';

const SOFT_FAIL_CODES = new Set(['ENCODING', 'PAYLOAD', 'HEADER', 'CLAIMS']);

function getAuthzMode(req) {
  return String(
    (req.headers && req.headers['x-authz-mode']) ||
    process.env.AUTHZ_MODE ||
    'compat'
  ).toLowerCase();
}

function shouldDeferAuthError(_req, _err) {
  return false;
}

module.exports = {
  SOFT_FAIL_CODES,
  shouldDeferAuthError,
  getAuthzMode,
};

