/**
 * JWT-style token validation middleware.
 *
 * Token format (compatible with our auth-service):
 *   base64url(header) . base64url(payload) . base64url(hmac-sha256)
 *
 * On success: sets req.user with decoded claims, calls next().
 */
'use strict';

const crypto = require('crypto');

const TOKEN_SECRET = process.env.TOKEN_SECRET || 'finguard-dev-secret-do-not-use-in-prod';

// Endpoints that never require authentication
const PUBLIC_PATHS = ['/api/health', '/api/version'];

// ─── Custom error for token issues ────────────────────────────────────

class TokenValidationError extends Error {
  constructor(message, code) {
    super(message);
    this.name = 'TokenValidationError';
    this.code = code || 'INVALID_TOKEN';
  }
}

// ─── Token verification ───────────────────────────────────────────────

/**
 * Verify and decode a signed token.
 *
 * @param {string} token – raw token string from the Authorization header
 * @returns {object} decoded payload claims
 * @throws {TokenValidationError}
 */
function _verifyToken(token) {
  if (typeof token !== 'string' || token.length === 0) {
    throw new TokenValidationError('Empty token', 'EMPTY');
  }

  const segments = token.split('.');
  if (segments.length !== 3) {
    throw new TokenValidationError('Token must have 3 dot-separated segments', 'MALFORMED');
  }

  const [headerB64, payloadB64, signatureB64] = segments;

  // Validate that each segment uses the base64url alphabet (RFC 4648 §5).
  // Standard base64 characters (+, /, =) are NOT permitted — tokens from
  // external systems that use standard encoding must be re-encoded first.
  const b64urlPattern = /^[A-Za-z0-9_-]+$/;
  for (const seg of [headerB64, payloadB64, signatureB64]) {
    // A base64url string with a length congruent to 1 modulo 4 cannot be
    // decoded, even though Buffer.from() will accept it and silently drop
    // trailing bits.  Re-encoding also rejects non-canonical encodings.
    if (!b64urlPattern.test(seg) || seg.length % 4 === 1 ||
        Buffer.from(seg, 'base64url').toString('base64url') !== seg) {
      throw new TokenValidationError(
        'Token segment contains invalid base64url encoding',
        'ENCODING',
      );
    }
  }

  // Verify HMAC-SHA256 signature
  const signedContent = headerB64 + '.' + payloadB64;
  const expectedSig = crypto
    .createHmac('sha256', TOKEN_SECRET)
    .update(signedContent)
    .digest('base64url');

  const sigBuf = Buffer.from(signatureB64, 'utf8');
  const expBuf = Buffer.from(expectedSig, 'utf8');
  if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
    throw new TokenValidationError('Signature verification failed', 'SIGNATURE');
  }

  // Decode header
  let header;
  try {
    header = JSON.parse(Buffer.from(headerB64, 'base64url').toString('utf8'));
  } catch (_) {
    throw new TokenValidationError('Invalid header JSON', 'HEADER');
  }
  if (!header || typeof header !== 'object' || Array.isArray(header) || header.alg !== 'HS256') {
    const algorithm = header && typeof header === 'object' ? header.alg : undefined;
    throw new TokenValidationError('Unsupported algorithm: ' + algorithm, 'ALGORITHM');
  }

  // Decode payload
  let payload;
  try {
    payload = JSON.parse(Buffer.from(payloadB64, 'base64url').toString('utf8'));
  } catch (_) {
    throw new TokenValidationError('Invalid payload JSON', 'PAYLOAD');
  }

  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    throw new TokenValidationError('Payload must be a JSON object', 'PAYLOAD');
  }

  if (!Object.prototype.hasOwnProperty.call(payload, 'sub') || payload.sub === null || payload.sub === '') {
    throw new TokenValidationError('Missing "sub" claim', 'CLAIMS');
  }
  if (!Object.prototype.hasOwnProperty.call(payload, 'role') || payload.role === null || payload.role === '') {
    throw new TokenValidationError('Missing "role" claim', 'CLAIMS');
  }

  // Check expiration
  if (payload.exp !== undefined &&
      (typeof payload.exp !== 'number' || !Number.isFinite(payload.exp))) {
    throw new TokenValidationError('Invalid expiration claim', 'CLAIMS');
  }
  if (payload.exp !== undefined && payload.exp < Math.floor(Date.now() / 1000)) {
    throw new TokenValidationError('Token has expired', 'EXPIRED');
  }

  return payload;
}

// ─── Middleware ────────────────────────────────────────────────────────

function tokenValidator(req, res, next) {
  // Public endpoints — skip authentication entirely
  if (PUBLIC_PATHS.includes(req.path)) {
    return next();
  }

  const authHeader = req.headers['authorization'] || '';

  // No Authorization header → clear rejection
  if (!authHeader) {
    return _reject(req, res, 401, 'Authentication required', 'AUTHENTICATION_REQUIRED');
  }

  // Wrong scheme
  if (typeof authHeader !== 'string' || !authHeader.startsWith('Bearer ')) {
    return _reject(req, res, 401, 'Invalid authentication scheme', 'AUTHENTICATION_SCHEME');
  }

  const token = authHeader.slice(7).trim();

  try {
    const claims = _verifyToken(token);

    // Attach decoded identity to the request
    req.user = {
      id:       claims.sub,
      role:     claims.role,
      username: claims.username || null,
    };

    next();
  } catch (err) {
    return _reject(req, res, 401, err.code === 'EXPIRED' ? 'Token expired' : 'Invalid token', err.code || 'INVALID_TOKEN');
  }
}

/**
 * Reject an authentication failure consistently and leave an audit trail.
 * Never include the raw token or decoded claims in the diagnostic.
 */
function _reject(req, res, status, error, code) {
  console.warn('[WARN] ' + req.method + ' ' + req.path + ': rejected authentication (' + code + ')');
  res.statusCode = status;
  return res.json({ error: error, code: code });
}

// ─── Token generation (used by auth-service & test harness) ───────────

function signToken(payload, opts) {
  opts = opts || {};
  const header = { alg: 'HS256', typ: 'JWT' };
  const now = Math.floor(Date.now() / 1000);
  const expiry = payload.exp !== undefined
    ? payload.exp
    : now + (opts.expiresIn !== undefined ? opts.expiresIn : 3600);
  const claims = Object.assign({}, payload, {
    iat: now,
    exp: expiry,
  });

  const headerB64  = Buffer.from(JSON.stringify(header)).toString('base64url');
  const payloadB64 = Buffer.from(JSON.stringify(claims)).toString('base64url');
  const signature  = crypto
    .createHmac('sha256', TOKEN_SECRET)
    .update(headerB64 + '.' + payloadB64)
    .digest('base64url');

  return headerB64 + '.' + payloadB64 + '.' + signature;
}

module.exports = { tokenValidator, signToken, _verifyToken, TOKEN_SECRET };

